    if (&seen0_flagFromAnalog_rxDeskew_lfsrPatternSent && &seen1_flagFromAnalog_rxDeskew_lfsrPatternSent) inputs_full++; else partial = {partial, " jtagLtsm_flagFromAnalog_rxDeskew_lfsrPatternSent"};
    if (&seen0_flagFromAnalog_rxDeskew_rxLaneDeskewApplied && &seen1_flagFromAnalog_rxDeskew_rxLaneDeskewApplied) inputs_full++; else partial = {partial, " jtagLtsm_flagFromAnalog_rxDeskew_rxLaneDeskewApplied"};
    if (&seen0_flagFromAnalog_rxDeskew_detectedDataPattern && &seen1_flagFromAnalog_rxDeskew_detectedDataPattern) inputs_full++; else partial = {partial, " jtagLtsm_flagFromAnalog_rxDeskew_detectedDataPattern"};
    if (&seen0_flagFromAnalog_d2cReceiver_laneComparisonSuccessful && &seen1_flagFromAnalog_d2cReceiver_laneComparisonSuccessful) inputs_full++; else partial = {partial, " jtagLtsm_flagFromAnalog_d2cReceiver_laneComparisonSuccessful"};
    if (&seen0_linkSpeed_requestedSpeed && &seen1_linkSpeed_requestedSpeed) inputs_full++; else partial = {partial, " jtagLtsm_linkSpeed_requestedSpeed"};
    if (&seen0_flagFromAnalog_linkSpeed_speedApplied && &seen1_flagFromAnalog_linkSpeed_speedApplied) inputs_full++; else partial = {partial, " jtagLtsm_flagFromAnalog_linkSpeed_speedApplied"};
    $display("testModeLtsm: %0d of 155 block outputs toggled, %0d of 67 block inputs saw every bit at 0 and 1", toggled, inputs_full);
    if (never != "" && toggled + 12 >= 155) $display("  outputs never toggled (route checked by the output walk):%s", never);
    else if (never != "") $display("  %0d outputs never toggled (routes checked by the output walk)", 155 - toggled);
    if (partial != "") fail({"block inputs not fully exercised:", partial});
    if (toggled == 0) fail("no block output ever toggled: ltsm is not running in testModeLtsm");
  endtask

  // ---------------------------------------------------------------------
  // Phases. Mode pins change only while every clock is stopped.
  // ---------------------------------------------------------------------
  task automatic run_phase(input phase_t ph, input int unsigned cycles);
    clk_en = 0;
    #20ns;
    phase = ph;
    testModeLtsm = (ph == PH_BLK);
    for (cycle = 0; cycle < cycles; cycle++) begin
      @(negedge tb_clk);
      if (cycle == 0) clk_en = 1;
      if (cycle > RESET_CYCLES) begin
        check_shadow();
        if (ph == PH_FUNC) check_tdr_zero(0);
        else begin
          if (cycle == RESET_CYCLES + 1) func_outs0 = func_outs;
          check_tdr_zero(1);
          check_block();
          sample_coverage(cycle == RESET_CYCLES + 1);
        end
      end
      drive(cycle);
    end
    clk_en = 0;
    $display("%s phase done: %0d cycles", ph == PH_BLK ? "testModeLtsm" : "functional", cycles);
  endtask

  initial begin : run_test
    int unsigned seed, blk_cycles;
    seed = 1;
    blk_cycles = 20000;
    void'($value$plusargs("SEED=%d", seed));
    void'($value$plusargs("CYCLES=%d", blk_cycles));
    void'($urandom(seed));
    $display("UcieDigitalTopTestModeLtsmSpec_tb: seed %0d, testModeLtsm phase %0d cycles", seed, blk_cycles);
    $warning("ltsm.cycles_1us has no jtagLtsm_cycles_1us TDR pin: in testModeLtsm it is fed from the functional pin cycles_1us");
    testModeDigital = 1'b0;
    testModeFdi = 1'b0;
    testModeLtsm = 1'b0;
    testModePhy = 1'b0;
    testModeRdi = 1'b0;
    zero_inputs();
    run_phase(PH_FUNC, FUNC_CYCLES);
    run_phase(PH_BLK, blk_cycles);
    run_phase(PH_FUNC, FUNC_CYCLES);
    output_walk(0, 8);
    phase = PH_BLK;
    testModeLtsm = 1'b1;
    output_walk(1, 8);
    report_coverage();
    if (errors != 0) $fatal(1, "FAIL: %0d errors", errors);
    $display("PASS: testModeLtsm: ltsm routed to jtagLtsm_* pins, matches reference, rest of the top isolated");
    $finish;
  end
endmodule

`default_nettype wire
